import 'dart:math' as math;
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:sehatak/core/models/child/child_models.dart';
class ChildService {final FirebaseFirestore _db=FirebaseFirestore.instance;CollectionReference<Map<String,dynamic>> get _doctors=>_db.collection('child_doctors');CollectionReference<Map<String,dynamic>> get _clinics=>_db.collection('child_clinics');CollectionReference<Map<String,dynamic>> get _tips=>_db.collection('child_tips');CollectionReference<Map<String,dynamic>> get _hospitals=>_db.collection('child_hospitals');CollectionReference<Map<String,dynamic>> get _consultations=>_db.collection('child_consultations');CollectionReference<Map<String,dynamic>> get _trackers=>_db.collection('child_growth_trackers');
Stream<List<ChildDoctor>>streamDoctors({String? specialty,int limit=20}){Query<Map<String,dynamic>>q=_doctors.limit(limit);if(specialty!=null&&specialty.isNotEmpty)q=q.where('specialty',isEqualTo:specialty);return q.snapshots().map((s)=>s.docs.map((d)=>ChildDoctor.fromFirestore(d.id,d.data())).toList());}Future<List<ChildDoctor>>getTopDoctors({int limit=6})async{final s=await _doctors.orderBy('rating',descending:true).limit(limit).get();return s.docs.map((d)=>ChildDoctor.fromFirestore(d.id,d.data())).toList();}Future<ChildDoctor?>getDoctor(String id)async{final d=await _doctors.doc(id).get();return d.exists?ChildDoctor.fromFirestore(id,d.data()!):null;}
Stream<List<ChildClinic>>streamClinics({int limit=20})=>_clinics.limit(limit).snapshots().map((s)=>s.docs.map((d)=>ChildClinic.fromFirestore(d.id,d.data())).toList());Future<List<ChildClinic>>getNearbyClinics(GeoPoint center,double radiusKm)async{final s=await _clinics.limit(100).get();return s.docs.map((d)=>ChildClinic.fromFirestore(d.id,d.data())).where((c)=>c.location!=null&&_distance(center,c.location!)<=radiusKm).toList();}double _distance(GeoPoint a,GeoPoint b){const r=6371.0,p=math.pi/180;final dl=(b.latitude-a.latitude)*p,dn=(b.longitude-a.longitude)*p,x=math.sin(dl/2)*math.sin(dl/2)+math.cos(a.latitude*p)*math.cos(b.latitude*p)*math.sin(dn/2)*math.sin(dn/2);return r*2*math.atan2(math.sqrt(x),math.sqrt(1-x));}
Stream<List<ChildTip>>streamTips({String? category,int limit=20}){Query<Map<String,dynamic>>q=_tips.where('isPublished',isEqualTo:true).limit(limit);if(category!=null&&category.isNotEmpty)q=q.where('category',isEqualTo:category);return q.snapshots().map((s)=>s.docs.map((d)=>ChildTip.fromFirestore(d.id,d.data())).toList());}Stream<List<ChildHospital>>streamHospitals({int limit=10})=>_hospitals.limit(limit).snapshots().map((s)=>s.docs.map((d)=>ChildHospital.fromFirestore(d.id,d.data())).toList());Future<String>createConsultation({required String userId,required String question,String doctorId=''})async{final r=_consultations.doc();await r.set({'userId':userId,'doctorId':doctorId,'question':question,'status':'pending','answer':'','createdAt':FieldValue.serverTimestamp()});return r.id;}Stream<List<ChildConsultation>>streamMyConsultations(String userId)=>_consultations.where('userId',isEqualTo:userId).snapshots().map((s)=>s.docs.map((d)=>ChildConsultation.fromFirestore(d.id,d.data())).toList());
Future<ChildGrowthTracker?>getTracker(String uid)async{final d=await _trackers.doc(uid).get();return d.exists?ChildGrowthTracker.fromFirestore(uid,d.data()!):null;}Stream<ChildGrowthTracker?>streamTracker(String uid)=>_trackers.doc(uid).snapshots().map((d)=>d.exists?ChildGrowthTracker.fromFirestore(uid,d.data()!):null);Future<void>addVaccination(String uid,Map<String,dynamic>vaccination)async=>_trackers.doc(uid).set({'vaccinations':FieldValue.arrayUnion([vaccination])},SetOptions(merge:true));Future<void>updateGrowth(String uid,{double?height,double?weight})async=>_trackers.doc(uid).set({'height':height,'weight':weight},SetOptions(merge:true));Future<void>updateBirthDate(String uid,DateTime birthDate)async=>_trackers.doc(uid).set({'birthDate':Timestamp.fromDate(birthDate)},SetOptions(merge:true));}
